    // seed- und toolchain-stabil (s. permutation_sampling.hpp). Nur wirksam bei messreihen_mode==FullSampled.
    std::uint32_t sample_rate = default_full_sampled_rate; // 1:1000 Default; <=1 deaktiviert Sampling
